window.__vpnChecked||(window.__vpnChecked=!0,document.addEventListener("DOMContentLoaded",async()=>{try{let e=await fetch("https://api.ipify.org?format=json"),t=await e.json(),r=t.ip;console.log("Client Public IP:",r);let a=await fetch(`/vpn.php?ip=${r}`),n=await a.json();if(console.log("IPQS Data:",n),n.error){console.error("Backend error:",n.message);return}let o=!0===n.active_vpn||!0===n.tor||!0===n.vpn&&n.fraud_score>75;if(console.log("Is VPN User:",o),o){let s=document.getElementsByTagName("body");s[0].classList.remove("d-none"),s[0].innerHTML=`
                    <div class="vpn_body">
                        <div class="vpn_card">
                            <p>
                                Looks like you are connecting through a VPN, proxy or "unblocker" service.
                                Please turn off any of these services and try again.
                            </p>
                            <button class="vpn_btn" onclick="location.reload()">Retry</button>
                            <img src="../" alt="" srcset="">
                        </div>
                    </div>
                    `}else document.getElementsByTagName("body")[0].classList.remove("d-none")}catch(i){console.error("Fetch error:",i)}}));